#include "NodeInboundMessage.h"
NodeInboundMessage::NodeInboundMessage():messageId_(0),sourceNodeId_(INVALID_NODE_ID),sourceAddress_{},payload_(nullptr),payloadLength_(0),valid_(false){}
NodeInboundMessage NodeInboundMessage::create(NodeMessageId mid,NodeId id,const NodeAddress& a,const uint8_t* p,size_t n){NodeInboundMessage r;if(mid==0||id==INVALID_NODE_ID||!a.isValid()||!p||n==0||n>NODE_RUNTIME_MAX_PAYLOAD_LENGTH)return r;r.messageId_=mid;r.sourceNodeId_=id;r.sourceAddress_=a;r.payload_=p;r.payloadLength_=n;r.valid_=true;return r;} bool NodeInboundMessage::isValid()const{return valid_&&messageId_!=0&&sourceNodeId_!=INVALID_NODE_ID&&sourceAddress_.isValid()&&payload_&&payloadLength_>0&&payloadLength_<=NODE_RUNTIME_MAX_PAYLOAD_LENGTH;} NodeMessageId NodeInboundMessage::messageId()const{return messageId_;} NodeId NodeInboundMessage::sourceNodeId()const{return sourceNodeId_;} const NodeAddress& NodeInboundMessage::sourceAddress()const{return sourceAddress_;} const uint8_t* NodeInboundMessage::payload()const{return payload_;} size_t NodeInboundMessage::payloadLength()const{return payloadLength_;}
